  rPeriod: (a, b) => `Période : du ${a} au ${b}`, rStart: d => `Début du programme : ${d} (programme de 28 semaines)`, rGen: d => `Généré le : ${d}`,
  rAboutT: "Le programme",
  rAbout: ["Mind Talks est une pratique quotidienne autonome, menée en parallèle d'une thérapie cognitivo-comportementale (TCC), pour les crises de panique, l'accélération du rythme cardiaque liée à l'anxiété et le vertige postural-perceptif persistant (PPPD).", "Chaque jour comporte trois courtes séances (environ 20 minutes au total) :"],
  rAboutItems: ["Matin : respiration rythmée, 4 s d'inspiration, 6 s d'expiration, 5 s de repos, pendant 5 minutes (environ 4 respirations par minute).", "Midi : habituation au vertige : station debout détendue, marche en tournant la tête et brève exposition au mouvement visuel.", "Soir : exercices cognitifs : compte à rebours de 7 en 7 (entraînement de l'attention), défusion cognitive (« Je remarque que j'ai la pensée que… ») et répétition de phrases apaisantes.", "En fin de journée, le vertige et l'anxiété sont chacun notés de 0 (aucun) à 10 (le pire)."],
  rResultsT: "Synthèse des résultats", rTrendT: "Vertige et anxiété par semaine", rWeeklyT: "Semaine par semaine", rDailyT: "Jour par jour",
  rThoughtsT: "Pensées quotidiennes", rThoughtsIntro: "Pensées écrites pendant l'exercice de détachement.", rNoThoughts: "Aucune pensée enregistrée sur cette période.",
  rNoData: "aucune saisie", rDisc: "Données auto-enregistrées. Les évaluations sont subjectives et ne constituent pas une mesure médicale.",
